"""Share of the total volume per trade."""
from trades import load_trades


def volume_shares(trades):
    """Return each trade's share of the total volume, in order."""
    total = sum(x.volume for x in trades)
    return [x.volume / total for x in trades]


def stored_shares():
    """Shares for the stored trades."""
    return volume_shares(load_trades())


def top_share(trades):
    """Return the largest share, or 0.0 when there are no trades."""
    shares = volume_shares(trades)
    return max(shares) if shares else 0.0


def largest_volume(trades):
    """Return the largest volume, or None when there are no trades."""
    values = [x.volume for x in trades]
    return max(values) if values else None


def describe_trade(trade):
    """Return a one-line description of a trade."""
    return "%s: %s" % (trade.desk, trade.volume)

